#!/usr/bin/env python3
# SPDX-License-Identifier: MPL-2.0
"""Generate the OpenGL ES 2.0 entry points of an NBT app module.

Each gl* function is a stub that jumps through a table the runner fills
(host ABI gl_proc), so a GL call costs one indirect branch into the driver,
like a call through the PLT.

Usage: gen_gl_table.py <gl.xml> <out.c>
"""
import sys

from glregistry import gles2_commands


def main():
    commands = gles2_commands(sys.argv[1])
    out = [
        "/* Generated by tools/gen_gl_table.py from Khronos gl.xml: OpenGL ES 2.0. */",
        "#include <GLES2/gl2.h>",
        "#include \"nbt_module.h\"",
        "",
        "#define NBT_GL_COUNT %d" % len(commands),
        "void* nbt_gl_table[NBT_GL_COUNT] NBT_HIDDEN;",
        "static const char* const nbt_gl_names[NBT_GL_COUNT] = {",
    ]
    out += ['  "%s",' % c.name for c in commands]
    out += [
        "};",
        "",
        "/* A missing entry point is a broken runner: say which and stop. */",
        "static void nbt_gl_missing(void) {",
        "  static const char msg[] = \"module: called an OpenGL ES function the runner did not provide\\n\";",
        "  nbt_host->write_output(2, msg, sizeof(msg) - 1);",
        "  nbt_host->exit_process(134);",
        "}",
        "",
        "/* Fills the table; returns how many entry points the runner lacks. */",
        "int nbt_gl_load(void) NBT_HIDDEN;",
        "int nbt_gl_load(void) {",
        "  int missing = 0;",
        "  for (int i = 0; i < NBT_GL_COUNT; ++i) {",
        "    void* p = NBT_HAS(gl_proc) ? nbt_host->gl_proc(nbt_gl_names[i]) : NULL;",
        "    if (!p) {",
        "      p = (void*)nbt_gl_missing;",
        "      ++missing;",
        "    }",
        "    nbt_gl_table[i] = p;",
        "  }",
        "  return missing;",
        "}",
        "",
    ]
    for i, c in enumerate(commands):
        call = "((%s (GL_APIENTRY *)(%s))nbt_gl_table[%d])(%s)" % (c.ret, c.types(), i, c.args())
        body = ("return " if c.ret != "void" else "") + call + ";"
        out.append("GL_APICALL %s GL_APIENTRY %s(%s) { %s }" % (c.ret, c.name, c.decl(), body))
    with open(sys.argv[2], "w") as f:
        f.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
